mapper.select:
SELECT ${resource.idColumn} AS id, name,

  ${resource.statusColumn} AS status,
  NULL AS status,

created_at AS createdAt, updated_at AS updatedAt, deleted_at AS deletedAt
FROM ${resource.tableName}
WHERE ${resource.idColumn} = #{id}

mapper.update:
UPDATE ${resource.tableName}
SET name = #{name}, updated_at = NOW()
, ${resource.statusColumn} = #{status}
WHERE ${resource.idColumn} = #{id} AND deleted_at IS NULL
